import { test, expect } from '@playwright/test';

test.describe('Sticky Footer Navigation on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display sticky footer navigation on mobile viewport', async ({ page }) => {
    // Set viewport to mobile
    await page.setViewportSize({ width: 375, height: 812 });

    // Verify footer navigation is visible
    const navLinks = page.getByRole('navigation').first();
    await expect(navLinks).toBeVisible();

    // Verify navigation links are accessible via role
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();

    const aboutLink = page.getByRole('link', { name: /about/i });
    await expect(aboutLink).toBeVisible();

    const contactLink = page.getByRole('link', { name: /contact/i });
    await expect(contactLink).toBeVisible();

    // Verify footer navigation is sticky
    const footerNav = page.getByRole('navigation');
    await expect(footerNav).toHaveAttribute('style', /position: sticky; top: 0;/);

    // Verify footer navigation is responsive
    await expect(footerNav).toHaveStyle('min-width: 100%;');
  });

  test('should maintain sticky footer navigation state after scrolling', async ({ page }) => {
    // Set viewport to mobile
    await page.setViewportSize({ width: 375, height: 812 });

    // Verify footer navigation is visible
    const navLinks = page.getByRole('navigation').first();
    await expect(navLinks).toBeVisible();

    // Scroll down to test stickiness
    const scrollContainer = page.locator('[data-testid="scroll-container"]');
    await scrollContainer.evaluate((el) => el.scrollTop = el.scrollHeight);

    // Verify footer navigation is still visible after scrolling
    await expect(navLinks).toBeVisible();

    // Verify footer navigation is still sticky
    await expect(footerNav).toHaveAttribute('style', /position: sticky; top: 0;/);

    // Verify footer navigation is responsive after scrolling
    await expect(footerNav).toHaveStyle('min-width: 100%;');
  });
});
